export type ParsedRejectInstruction<
  TProgram extends string = typeof AGENT_ESCROW_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    job: TAccountMetas[1];
    client: TAccountMetas[2];
    mint: TAccountMetas[3];
    vault: TAccountMetas[4];
    clientToken: TAccountMetas[5];
    /** Required whenever the provider had accepted the job, so its record is updated. */
    providerProfile?: TAccountMetas[6] | undefined;
    tokenProgram: TAccountMetas[7];
  };
  data: RejectInstructionData;
};

export function parseRejectInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRejectInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === AGENT_ESCROW_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      job: getNextAccount(),
      client: getNextAccount(),
      mint: getNextAccount(),
      vault: getNextAccount(),
      clientToken: getNextAccount(),
      providerProfile: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getRejectInstructionDataDecoder().decode(instruction.data),
  };
}
